import React from 'react';

// The 'Hero' constant is now correctly defined and exported below
const Hero = () => {
  return (
    <section className="bg-gray-50 py-16 px-4">
      <div className="container mx-auto">
        <h2 className="text-center text-4xl font-bold text-brand-orange mb-8">
          Getting to Know <br />
          <span className="text-brand-blue">"Coimbatore Dietitian Pradeepa"</span>
        </h2>
        {/* The parent div now centers the text content on the page */}
        <div className="flex justify-center">
          <div className="text-center max-w-3xl space-y-4 text-lg leading-relaxed">
            <p><strong>Pradeepa Saravanan</strong> is a Coimbatore-based consultant Dietitian/Nutritionist...</p>
            <p>She says, Diet is the cornerstone of health and vitality...</p>
            <button className="bg-brand-green hover:bg-brand-green-dark text-white font-bold py-3 px-6 rounded-lg transition-colors mt-4">
              How do you feel being a dietitian?
            </button>
          </div>
        </div>
      </div>
    </section>
  );
};

// This line was missing. It makes the component available for other files to import.
export default Hero;
